function Pick({label,value,onChange,options}:{label:string,value:string,onChange:(v:string)=>void,options:{value:string,label:string}[]}){return <label className="filter"><span>{label}</span><Select value={value||'__all'} items={[{value:'__all',label:'Todos'},...options]} onValueChange={v=>onChange(v==='__all'?'':String(v))}><SelectTrigger><span>{options.find(x=>x.value===value)?.label||'Todos'}</span></SelectTrigger><SelectContent><SelectItem value="__all">Todos</SelectItem>{options.map(o=><SelectItem key={o.value} value={o.value}>{o.label}</SelectItem>)}</SelectContent></Select></label>}
function Grid({rows,fields,onOpen}:{rows:Row[],fields:string[],onOpen?:(r:Row)=>void}){return rows.length?<div className="intel-table"><Table><TableHeader><TableRow>{fields.map(k=><TableHead key={k}>{labels[k]||k}</TableHead>)}{onOpen&&<TableHead>Detalhes</TableHead>}</TableRow></TableHeader><TableBody>{rows.map((r,i)=><TableRow key={r.id||i}>{fields.map(k=><TableCell key={k}>{k==='pending'?(r.pending||[]).map((p:Row)=>p.label).join(' · ')||'Sem pendências':fmt(r[k])}</TableCell>)}{onOpen&&<TableCell><Button variant="outline" onClick={()=>onOpen(r)}>Abrir</Button></TableCell>}</TableRow>)}</TableBody></Table></div>:<div className="empty"><Database/><p>Nenhum registro disponível neste recorte. Informações desconhecidas não são preenchidas automaticamente.</p></div>}
function Details({data}:{data:Row}){return <dl className="intel-details">{Object.entries(data).map(([k,v])=><div key={k}><dt>{labels[k]||k.replaceAll('_',' ')}</dt><dd>{v&&typeof v==='object'?<Details data={Array.isArray(v)?Object.fromEntries(v.map((r,i)=>[String(i+1),r])):v}/>:typeof v==='string'&&v.startsWith('http')?<a href={v} target="_blank" rel="noreferrer">Abrir fonte <ArrowUpRight size={13}/></a>:fmt(v)}</dd></div>)}</dl>}

function Passport({data,editable,onSave}:{data:Row,editable:boolean,onSave:(values:Record<string,string|null>)=>Promise<any>}){
 const [draft,setDraft]=useState<Record<string,string|null>>({...data.values}),[saving,setSaving]=useState(false);
 const [search,setSearch]=useState('');
 const fields=data.fields.filter((f:Row)=>(f.label+' '+f.description).toLowerCase().includes(search.toLowerCase()));
 return <section className="passport"><h2>Registro digital da bateria</h2><p>{data.filled} de {data.total} campos preenchidos · Dados pendentes podem ser adicionados futuramente.</p><p>Estrutura baseada na lista do projeto. O código interno identifica o cadastro; o identificador oficial será informado quando disponível.</p><label className="filter"><span>Buscar nos 71 campos</span><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Ex.: capacidade, fabricante, saúde"/></label>{Array.from(new Set(fields.map((f:Row)=>f.group))).map(group=><fieldset key={String(group)}><legend>{String(group)}</legend>{fields.filter((f:Row)=>f.group===group).map((f:Row)=><label className="filter passport-field" key={f.id}><span>{f.id}. {f.label} <small>{draft[f.id]?'Preenchido':'Pendente'}</small></span><p>{f.description}</p>{editable&&!(['61','62','67','68','70','71'].includes(f.id)&&f.id in data.inherited)?<textarea value={draft[f.id]??''} maxLength={10000} placeholder="Não informado — preencher quando disponível" onChange={e=>setDraft({...draft,[f.id]:e.target.value||null})}/>:<strong>{draft[f.id]||'Não informado'}</strong>}</label>)}</fieldset>)}{editable&&<Button disabled={saving} onClick={async()=>{setSaving(true);try{await onSave(Object.fromEntries(Object.entries(draft).filter(([id,value])=>value!==(data.values[id]??null))))}finally{setSaving(false)}}}>{saving?'Salvando…':'Salvar dados da bateria'}</Button>}</section>
}

