 const [schemas,setSchemas]=useState<Row>({}),[formType,setFormType]=useState('sources'),[form,setForm]=useState<Row>({}),[allSources,setAllSources]=useState<Row[]>([]),[importText,setImportText]=useState(''),[lookup,setLookup]=useState(''),[resolveId,setResolveId]=useState(''),[forecastYear,setForecastYear]=useState('2026'),[forecast,setForecast]=useState<Row|null>(null),[tabularFile,setTabularFile]=useState<File|null>(null),[tabularSource,setTabularSource]=useState(''),[scheduler,setScheduler]=useState<Row|null>(null),[evidenceId,setEvidenceId]=useState(''),[reviewNotes,setReviewNotes]=useState(''),[publishSource,setPublishSource]=useState('');
 const api=useCallback(async (path:string,body?:any,signal?:AbortSignal)=>{const r=await fetch('/api/v2'+path,{method:body===undefined?'GET':'POST',headers:{'Content-Type':'application/json',...(key?{'X-Admin-Key':key,'X-API-Key':key}:{})},body:body===undefined?undefined:JSON.stringify(body),signal});const result:any=await r.json();if(!r.ok)throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result.detail));return result},[key]);
