 const sourceOptions=(market?.sources||[]).filter((s:Row)=>['fleet_stock','registrations'].includes(s.metric)).map((s:Row)=>({value:s.id,label:`${s.provider} · ${s.dataset_name} · ${s.reference_period}`}));
 async function unlock(){await action(async()=>{const s=await api('/session');setRole(s.role);if(s.role==='public_user')throw Error('Credencial não reconhecida');if(['admin','data_engineer'].includes(s.role)){setSchemas(await api('/contracts'));setAllSources(await api('/admin/sources'))}return s},'Acesso autorizado. A chave fica somente nesta página.')}
