 async function openAggregateVehicles(record:Row){
  const q=new URLSearchParams({manufacturer:String(record.manufacturer||''),model:String(record.model||''),powertrain_type:String(record.powertrain_type||''),vehicle_category:String(record.vehicle_category||''),limit:'200'});
  try{setBusy(true);setError('');const response=await fetch('/api/v3/models?'+q);const data=await response.json();if(!response.ok)throw Error(data.detail||'Não foi possível localizar os veículos desta categoria.');const group=(data.items||[]).find((item:Row)=>String(item.manufacturer).toLowerCase()===String(record.manufacturer||'').toLowerCase()&&String(item.model).toLowerCase()===String(record.model||'').toLowerCase()&&String(item.powertrain_type||'')===String(record.powertrain_type||'')&&String(item.vehicle_category||'')===String(record.vehicle_category||''))||data.items?.[0];if(!group)throw Error('Esta categoria não pertence à frota ativa atual.');window.location.href='/veiculos/modelos/'+group.id}catch(e:any){setError(e.message)}finally{setBusy(false)}
 }
